class Solution:
    def countHousePlacements(self, n: int) -> int:
        MOD = 10**9 + 7
        a, b = 1, 2
        for _ in range(n - 1):
            a, b = b, (a + b) % MOD
        return b * b % MOD

c.cpp:
class Solution {
public:
    int countHousePlacements(int n) {
        const long long MOD = 1e9 + 7;
        long long a = 1, b = 2;
        for (int i = 1; i < n; i++) {
            long long c = (a + b) % MOD;
            a = b; b = c;
        }
        return (int)(b * b % MOD);
    }
};

